INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_MELICERTES_PALAEMON_OVIDM','ENT_MELICERTES_PALAEMON','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 4.519-542:','The Romans gave the name of Matuta to Ino, and Melicerta, or Palaemon, was called Portunus. The circumstance mentioned by Ovid, that some of Ino''s attendants were changed into birds, and others into rocks, is, perhaps, only a poetical method of saying that some of her attendants escaped, while others perished with her. FABLE VIII.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ROM_DIVUS_JULIUS_OVIDM','ENT_ROM_DIVUS_JULIUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 15.745-870:','It is a matter of doubt whether he here refers to the conspiracies of Brutus and Cassius against Julius Caesar, or whether to that against Augustus, which is mentioned by Suetonius, in the nineteenth chapter of his History. As Augustus survived the latter conspiracy, and the parallel is thereby rendered more complete, probably this is the circumstance here alluded to.] EXPLANATION.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ARETHUSA_OVIDM','ENT_ARETHUSA','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','462-563] Ceres proceeds in a fruitless search for her daughter over the whole earth, until the Nymph Arethusa acquaints her with the place of her ravisher''s abode. The Goddess makes her complaint to Jupiter, and obtains his consent for her daughter''s return to the upper world, provided she has not eaten anything since her arrival in Pluto''s dominions.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_DAPHNE_OVIDM','ENT_DAPHNE','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','[I.452-567] Apollo, falling in love with Daphne, the daughter of the river Peneus, she flies from him. He pursues her; on which, the Nymph, imploring the aid of her father, is changed into a laurel. Daphne, the daughter of Peneus, was the first love of Phœbus; whom, not blind chance, but the vengeful anger of Cupid assigned to him.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GLAUCUS_OVIDM','ENT_GLAUCUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','In his honor, Glaucus established the Isthmian games, which were celebrated for many ages at Corinth; and, being interrupted for a time, were revived by Theseus, in honor of Neptune. Leucothoe was also worshipped at Rome, and the Roman women used to offer up their vows to her for their brothers'' children, not daring to supplicate the Goddess for their own, because she had been unfortunate in hers. This Ovid tells us in the Sixth Book of the Fasti.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HERMAPHRODITUS_OVIDM','ENT_HERMAPHRODITUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses',', becoming jealous of her sister, was transformed into a sun-flower; and how Salmacis and Hermaphroditus had become united into one body. After this, through the agency of Bacchus, the sisters are transformed into bats, and their webs are changed into vines.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORPHNE_OVIDM','ENT_ORPHNE','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','He was the son of Acheron, by the Nymph Orphne, or Gorgyra, according to Apollodorus. The latter author says, that for his unseasonable discovery, Ceres placed a rock upon him; but that, having been liberated by Hercules, she changed him into an owl, called ωτον.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_SALMACIS_OVIDM','ENT_SALMACIS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','Then, indeed, Salmacis is astonished, and burns with desire for his naked beauty. The eyes, too, of the Nymph are on fire, no otherwise than as when the Sun, most brilliant with his clear orb, is reflected from the opposite image of a mirror. With difficulty does she endure delay; hardly does she now defer her joy. Now she longs to embrace him; and now, distracted, she can hardly contain herself.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_SYRINX_OVIDM','ENT_SYRINX','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Ovid, Metamorphoses','She is entrusted by Juno to the care of Argus; Mercury having first related to him the transformation of the Nymph Syrinx into reeds, slays him, on which his eyes are placed by Juno in the tail of the peacock. Io, having recovered human shape, becomes the mother of Epaphus. BOOK II.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation located by name; the locus is the Latin line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
